"use client"

import * as React from "react"
import { zodResolver } from "@hookform/resolvers/zod"
import { Check, Loader2, Plus, Trash2 } from "lucide-react"
import { useFieldArray, useForm, useWatch } from "react-hook-form"
import { gooeyToast } from "@/components/ui/goey-toaster"

import { accountStatusLabels } from "@/components/account-status-badge"
import { Button } from "@/components/ui/button"
import { DatePicker, toDateKey } from "@/components/ui/date-picker"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form"
import { Input } from "@/components/ui/input"
import { PhoneInput } from "@/components/ui/phone-input"
import { ProfileImageUpload } from "@/components/profile-image-upload"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Separator } from "@/components/ui/separator"
import {
  PILOT_PROGRAM_CODE,
  PILOT_YEAR_LEVEL,
} from "@/features/academic/pilot"
import {
  campusPickerOptions,
  isOfferedCampus,
  sectionPickerOptions,
  type ClassGroupingOption,
} from "@/features/academic/schema"
import {
  createTeacherAction,
  updateTeacherAction,
} from "@/features/teachers/actions"
import type {
  CourseOption,
  ProgramOption,
  TeacherView,
} from "@/features/teachers/directory"
import {
  accountStatuses,
  civilStatusOptions,
  genderOptions,
  teacherDialogSchema,
  type TeacherDialogValues,
} from "@/features/teachers/schema"
import { cn } from "@/lib/utils"

type StepId = "personal" | "employment" | "assignments" | "account"

interface WizardStep {
  id: StepId
  label: string
  title: string
  description: string
  /** Only these fields are validated before the step may be left. */
  fields: (keyof TeacherDialogValues)[]
}

const steps: WizardStep[] = [
  {
    id: "personal",
    label: "Personal Info",
    title: "Personal Information",
    description: "Identity and contact details for the teacher.",
    fields: [
      "fullName",
      "email",
      "gender",
      "civilStatus",
      "dateOfBirth",
      "phoneNumber",
      "profilePicture",
    ],
  },
  {
    id: "employment",
    label: "Employment",
    title: "Employment Information",
    description: "Institutional identifiers and account state.",
    fields: ["teacherId", "department", "dateHired", "status"],
  },
  {
    id: "assignments",
    label: "Assignments",
    title: "Teaching Assignments",
    description:
      "Classes from Academic Setup. A teacher can handle several without duplicating the profile.",
    fields: ["assignments"],
  },
  {
    id: "account",
    label: "Account",
    title: "Account Information",
    description:
      "The login account is created on the server; passwords are never stored in this database.",
    fields: ["password", "confirmPassword"],
  },
]

const emptyAssignment = {
  programId: "",
  courseId: "",
  yearLevel: PILOT_YEAR_LEVEL,
  section: "",
  campus: "",
}

const buttonMotion = "transition-transform active:scale-[0.96]"

function defaultValues(teacher?: TeacherView | null): TeacherDialogValues {
  if (!teacher) {
    return {
      mode: "create",
      fullName: "",
      gender: "",
      dateOfBirth: "",
      civilStatus: "",
      email: "",
      phoneNumber: "",
      profilePicture: "",
      teacherId: "",
      department: "",
      dateHired: "",
      status: "active",
      assignments: [{ ...emptyAssignment }],
      password: "",
      confirmPassword: "",
    }
  }

  return {
    mode: "edit",
    fullName: teacher.fullName,
    gender: (teacher.gender ?? "") as TeacherDialogValues["gender"],
    dateOfBirth: teacher.dateOfBirth ?? "",
    civilStatus: (teacher.civilStatus ??
      "") as TeacherDialogValues["civilStatus"],
    email: teacher.email,
    phoneNumber: teacher.phoneNumber ?? "",
    profilePicture: teacher.profilePicture ?? "",
    teacherId: teacher.teacherId,
    department: teacher.department,
    dateHired: teacher.dateHired ?? "",
    status: teacher.status,
    assignments:
      teacher.assignments.length > 0
        ? teacher.assignments.map((assignment) => ({
            assignmentId: assignment.id,
            programId: String(assignment.programId),
            courseId: String(assignment.courseId),
            yearLevel: assignment.yearLevel || PILOT_YEAR_LEVEL,
            section: assignment.section ?? "",
            campus: assignment.campus ?? "",
          }))
        : [{ ...emptyAssignment }],
    password: "",
    confirmPassword: "",
  }
}

/** Numbered progress rail: done, current, and still-to-come steps. */
function Stepper({ current, onStepChange, disabled = false }: {
  current: number
  onStepChange?: (step: number) => void
  disabled?: boolean
}) {
  return (
    <ol className="flex items-start" aria-label={onStepChange ? "Edit teacher steps" : "Add teacher progress"}>
      {steps.map((step, index) => {
        const isDone = !onStepChange && index < current
        const isCurrent = index === current

        return (
          <li
            key={step.id}
            className="flex min-w-0 flex-1 flex-col items-center last:flex-none"
          >
            <button
              type="button"
              aria-label={`Step ${index + 1}: ${step.label}`}
              aria-current={isCurrent ? "step" : undefined}
              disabled={!onStepChange || disabled}
              onClick={() => onStepChange?.(index)}
              className="flex w-full flex-col items-center gap-1.5 rounded-md text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring enabled:cursor-pointer disabled:cursor-default"
            >
            <div className="flex w-full items-center gap-2">
              <span
                aria-hidden
                className={cn(
                  "flex size-7 shrink-0 items-center justify-center rounded-full border text-xs tabular-nums",
                  isDone && "border-primary bg-primary text-primary-foreground",
                  isCurrent && "border-2 border-primary font-semibold",
                  !isDone && !isCurrent && "text-muted-foreground"
                )}
              >
                {isDone ? <Check className="size-3.5" /> : index + 1}
              </span>
              {index < steps.length - 1 ? (
                <span
                  aria-hidden
                  className={cn(
                    "h-px flex-1",
                    isDone ? "bg-primary" : "bg-border"
                  )}
                />
              ) : null}
            </div>
            <span
              className={cn(
                "text-xs",
                isCurrent ? "font-medium" : "text-muted-foreground"
              )}
            >
              {step.label}
              {isCurrent ? <span className="sr-only"> (current step)</span> : null}
            </span>
            </button>
          </li>
        )
      })}
    </ol>
  )
}

function SummaryRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex gap-2">
      <dt className="w-24 shrink-0 text-muted-foreground">{label}</dt>
      <dd className="min-w-0 flex-1 break-words">{value}</dd>
    </div>
  )
}

export function TeacherFormDialog({
  open,
  onOpenChange,
  teacher,
  programs,
  courses,
  groupings,
  departments,
}: {
  open: boolean
  onOpenChange: (open: boolean) => void
  /** Present when editing; absent when adding. */
  teacher?: TeacherView | null
  programs: ProgramOption[]
  courses: CourseOption[]
  /** Academic Setup groupings behind the section and campus pickers. */
  groupings: ClassGroupingOption[]
  departments: string[]
}) {
  const mode = teacher ? "edit" : "create"
  const departmentListId = React.useId()
  const [stepIndex, setStepIndex] = React.useState(0)
  const [isUploading, setIsUploading] = React.useState(false)

  // Default new assignments to the existing program.
  const bsitProgram = programs.find(
    (program) => program.code === PILOT_PROGRAM_CODE
  )
  const bsitProgramIdValue = bsitProgram ? String(bsitProgram.id) : ""

  const form = useForm<TeacherDialogValues>({
    resolver: zodResolver(teacherDialogSchema),
    defaultValues: defaultValues(teacher),
    mode: "onTouched",
  })

  const assignments = useFieldArray({
    control: form.control,
    name: "assignments",
  })

  // Reopening the dialog for another teacher must not show stale values.
  // Create mode starts on step one.
  React.useEffect(() => {
    if (!open) return

    const values = defaultValues(teacher)

    if (!teacher && bsitProgramIdValue) {
      values.assignments = values.assignments.map((assignment) => ({
        ...assignment,
        programId: bsitProgramIdValue,
        yearLevel: PILOT_YEAR_LEVEL,
      }))
    }

    form.reset(values)
    setStepIndex(0)
  }, [open, teacher, form, bsitProgramIdValue])

  const watchedAssignments = useWatch({
    control: form.control,
    name: "assignments",
  })
  const summary = useWatch({ control: form.control })

  // Dates are recorded, never scheduled, so tomorrow is out of range.
  const today = toDateKey(new Date())
  const isSubmitting = form.formState.isSubmitting || isUploading
  const step = steps[stepIndex]
  const isLastStep = stepIndex === steps.length - 1

  async function goNext() {
    if (isSubmitting) return
    const valid = await form.trigger(step.fields, { shouldFocus: true })

    if (valid) setStepIndex((current) => Math.min(current + 1, steps.length - 1))
  }

  function goBack() {
    // Going back never validates, so a half-filled step is not blocked.
    setStepIndex((current) => Math.max(current - 1, 0))
  }

  async function handleStepChange(target: number) {
    if (target === stepIndex || isSubmitting) return
    if (target < stepIndex) {
      setStepIndex(target)
      return
    }
    // Forward jumps validate every step left behind. Never saves — only moves locally.
    for (let index = stepIndex; index < target; index += 1) {
      const valid = await form.trigger(steps[index].fields, {
        shouldFocus: true,
      })
      if (!valid) {
        setStepIndex(index)
        return
      }
    }
    setStepIndex(target)
  }

  function handleFormKeyDown(event: React.KeyboardEvent<HTMLFormElement>) {
    if (event.key !== "Enter") return
    const target = event.target as HTMLElement | null
    if (!target) return
    if (
      target.tagName === "TEXTAREA" ||
      target.tagName === "BUTTON" ||
      target.closest("[data-no-wizard-next]")
    ) {
      return
    }
    // Enter on an early step moves forward instead of auto-saving.
    event.preventDefault()
    if (!isLastStep) void goNext()
  }

  function handleFormSubmit(event: React.FormEvent<HTMLFormElement>) {
    // Navigation and implicit Enter submissions never authorize a save.
    event.preventDefault()
  }

  function handleSave() {
    if (!isLastStep || isSubmitting) return
    void form.handleSubmit(onSubmit, (errors) => {
      const owning = steps.findIndex((entry) =>
        entry.fields.some((field) => field in errors)
      )
      if (owning >= 0) setStepIndex(owning)
    })()
  }

  async function onSubmit(values: TeacherDialogValues) {
    const result =
      mode === "create"
        ? await createTeacherAction(values)
        : await updateTeacherAction({ ...values, id: teacher?.id ?? 0 })

    if (!result.ok) {
      for (const [path, message] of Object.entries(result.fieldErrors ?? {})) {
        form.setError(path as keyof TeacherDialogValues, { message })
      }

      // Send the administrator to the step that owns the first failed field.
      const failed = (Object.keys(result.fieldErrors ?? {})[0] ?? "").split(
        "."
      )[0]
      const owning = steps.findIndex((entry) =>
        entry.fields.includes(failed as keyof TeacherDialogValues)
      )

      if (owning >= 0) setStepIndex(owning)

      gooeyToast.error(result.message)
      return
    }

    gooeyToast.success(result.message)
    onOpenChange(false)
  }

  const assignmentCount = watchedAssignments?.length ?? 0

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-h-[90svh] overflow-y-auto sm:max-w-3xl">
        <DialogHeader>
          <DialogTitle className="text-balance">
            {mode === "create" ? "Add Teacher" : "Edit Teacher"}
          </DialogTitle>
          <DialogDescription className="sr-only">
            Step {stepIndex + 1} of {steps.length}: {step.title}
          </DialogDescription>
        </DialogHeader>

        <Stepper current={stepIndex} onStepChange={mode === "edit" ? handleStepChange : undefined} disabled={isSubmitting} />

        <Form {...form}>
          <form
            onSubmit={handleFormSubmit}
            onKeyDown={handleFormKeyDown}
            className="space-y-6"
            noValidate
          >
            <div className="space-y-1">
              <h3 className="text-sm font-semibold text-balance">
                Step {stepIndex + 1} of {steps.length}: {step.title}
              </h3>
              <p className="text-sm text-muted-foreground text-pretty">
                {step.description}
              </p>
            </div>

            <div className="min-h-[20rem]">
              {step.id === "personal" ? (
                <div className="grid items-start gap-4 sm:grid-cols-2">
                  <FormField
                    control={form.control}
                    name="fullName"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Full name</FormLabel>
                        <FormControl>
                          <Input
                            autoComplete="name"
                            placeholder="Enter full name"
                            {...field}
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="email"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Email address</FormLabel>
                        <FormControl>
                          <Input
                            type="email"
                            autoComplete="email"
                            placeholder="Enter email address"
                            {...field}
                          />
                        </FormControl>
                        <FormDescription>
                          Also used as the login identifier.
                        </FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="gender"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Gender</FormLabel>
                        <Select
                          value={field.value}
                          onValueChange={field.onChange}
                        >
                          <FormControl>
                            <SelectTrigger className="w-full">
                              <SelectValue placeholder="Select gender" />
                            </SelectTrigger>
                          </FormControl>
                          <SelectContent>
                            {genderOptions.map((option) => (
                              <SelectItem key={option} value={option}>
                                {option}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="civilStatus"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Civil status</FormLabel>
                        <Select
                          value={field.value}
                          onValueChange={field.onChange}
                        >
                          <FormControl>
                            <SelectTrigger className="w-full">
                              <SelectValue placeholder="Select civil status" />
                            </SelectTrigger>
                          </FormControl>
                          <SelectContent>
                            {civilStatusOptions.map((option) => (
                              <SelectItem key={option} value={option}>
                                {option}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="dateOfBirth"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Date of birth</FormLabel>
                        <FormControl>
                          <DatePicker
                            value={field.value}
                            onChange={field.onChange}
                            onBlur={field.onBlur}
                            max={today}
                            placeholder="Select date of birth"
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="phoneNumber"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Phone number</FormLabel>
                        <FormControl>
                          <PhoneInput
                            autoComplete="tel"
                            name={field.name}
                            ref={field.ref}
                            value={field.value}
                            onChange={field.onChange}
                            onBlur={field.onBlur}
                            disabled={field.disabled}
                          />
                        </FormControl>
                        <FormDescription>
                          Mobile number without the leading 0 (e.g., 9181234567).
                        </FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="profilePicture"
                    render={({ field }) => (
                      <FormItem className="sm:col-span-2">
                        <FormLabel>
                          Profile picture{" "}
                          <span className="font-normal text-muted-foreground">
                            (optional)
                          </span>
                        </FormLabel>
                        <FormControl>
                          <ProfileImageUpload
                            key={`${teacher?.id ?? "new"}-${open}`}
                            onUploadingChange={setIsUploading}
                            disabled={form.formState.isSubmitting}
                            {...field}
                          />
                        </FormControl>
                        <FormDescription>
                          JPG, PNG, or WebP, up to 2 MB. Initials are shown when no image is selected.
                        </FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </div>
              ) : null}

              {step.id === "employment" ? (
                <div className="grid gap-4 sm:grid-cols-2">
                  <FormField
                    control={form.control}
                    name="teacherId"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Teacher ID</FormLabel>
                        <FormControl>
                          <Input
                            placeholder="Enter teacher ID (e.g., T-001)"
                            {...field}
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="department"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Department</FormLabel>
                        <FormControl>
                          <Input
                            list={departmentListId}
                            placeholder="Enter department"
                            {...field}
                          />
                        </FormControl>
                        <datalist id={departmentListId}>
                          {departments.map((department) => (
                            <option key={department} value={department} />
                          ))}
                        </datalist>
                        <FormDescription>
                          Pick an existing department, or type a new one.
                        </FormDescription>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="dateHired"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Date hired</FormLabel>
                        <FormControl>
                          <DatePicker
                            value={field.value}
                            onChange={field.onChange}
                            onBlur={field.onBlur}
                            max={today}
                            placeholder="Select the hire date"
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                  <FormField
                    control={form.control}
                    name="status"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Status</FormLabel>
                        <Select
                          value={field.value}
                          onValueChange={field.onChange}
                        >
                          <FormControl>
                            <SelectTrigger className="w-full">
                              <SelectValue placeholder="Select status (default: Active)" />
                            </SelectTrigger>
                          </FormControl>
                          <SelectContent>
                            {accountStatuses.map((option) => (
                              <SelectItem key={option} value={option}>
                                {accountStatusLabels[option]}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </div>
              ) : null}

              {step.id === "assignments" ? (
                <div className="space-y-4">
                  <ul className="space-y-3">
                    {assignments.fields.map((assignmentField, index) => {
                      const watched = watchedAssignments?.[index]
                      const selectedProgram = watched?.programId ?? ""
                      const selectedCourse = watched?.courseId ?? ""
                      // Archived subjects leave the picker; a saved one stays visible.
                      const programCourses = courses.filter(
                        (course) =>
                          String(course.programId) === selectedProgram &&
                          (course.status === "active" ||
                            String(course.id) === selectedCourse)
                      )
                      // Section and campus options come from the Academic Setup catalog.
                      const groupingScope = {
                        programId: selectedProgram ? Number(selectedProgram) : null,
                        yearLevel: watched?.yearLevel || PILOT_YEAR_LEVEL,
                      }
                      const sectionOptions = sectionPickerOptions(groupings, {
                        ...groupingScope,
                        current: watched?.section ?? "",
                      })
                      const campusOptions = campusPickerOptions(groupings, {
                        ...groupingScope,
                        section: watched?.section ?? "",
                        current: watched?.campus ?? "",
                      })

                      return (
                        <li
                          key={assignmentField.id}
                          className="rounded-lg border p-3"
                        >
                          <div className="mb-3 flex items-center justify-between gap-2">
                            <p className="text-sm font-medium tabular-nums">
                              Assignment {index + 1}
                            </p>
                            <Button
                              type="button"
                              variant="ghost"
                              size="sm"
                              className={buttonMotion}
                              disabled={assignments.fields.length === 1}
                              aria-label={`Remove assignment ${index + 1}`}
                              onClick={() => assignments.remove(index)}
                            >
                              <Trash2 aria-hidden />
                              Remove
                            </Button>
                          </div>

                          <div className="grid items-start gap-3 sm:grid-cols-2 lg:grid-cols-3">
                            <FormField
                              control={form.control}
                              name={`assignments.${index}.programId`}
                              render={({ field }) => (
                                <FormItem>
                                  <FormLabel>Program</FormLabel>
                                  <Select
                                    value={field.value}
                                    onValueChange={(value) => {
                                      field.onChange(value)
                                      form.setValue(`assignments.${index}.courseId`, "")
                                      form.setValue(`assignments.${index}.yearLevel`, "")
                                      form.setValue(`assignments.${index}.section`, "")
                                      form.setValue(`assignments.${index}.campus`, "")
                                    }}
                                  >
                                    <FormControl>
                                      <SelectTrigger className="w-full">
                                        <SelectValue placeholder="Select program" />
                                      </SelectTrigger>
                                    </FormControl>
                                    <SelectContent>
                                      {programs.map((program) => (
                                        <SelectItem key={program.id} value={String(program.id)}>
                                          {program.code} - {program.name}
                                        </SelectItem>
                                      ))}
                                    </SelectContent>
                                  </Select>
                                  <FormMessage />
                                </FormItem>
                              )}
                            />
                            <FormField
                              control={form.control}
                              name={`assignments.${index}.courseId`}
                              render={({ field }) => (
                                <FormItem className="min-w-0">
                                  <FormLabel>Course/Subject</FormLabel>
                                  <Select
                                    value={field.value}
                                    onValueChange={field.onChange}
                                    disabled={!selectedProgram}
                                  >
                                    <FormControl>
                                      <SelectTrigger className="w-full min-w-0 max-w-full overflow-hidden [&_[data-slot=select-value]]:min-w-0 [&_[data-slot=select-value]]:block [&_[data-slot=select-value]]:truncate">
                                        <SelectValue
                                          placeholder={
                                            selectedProgram
                                              ? "Select course"
                                              : "Select a program first"
                                          }
                                        />
                                      </SelectTrigger>
                                    </FormControl>
                                    <SelectContent className="max-w-[var(--radix-select-content-available-width)]">
                                      {programCourses.map((course) => (
                                        <SelectItem
                                          key={course.id}
                                          className="whitespace-normal break-words"
                                          value={String(course.id)}
                                        >
                                          {course.code} — {course.name}
                                          {course.status === "active"
                                            ? ""
                                            : ` (${accountStatusLabels[course.status].toLowerCase()})`}
                                        </SelectItem>
                                      ))}
                                    </SelectContent>
                                  </Select>
                                  {selectedProgram &&
                                  programCourses.length === 0 ? (
                                    <FormDescription>
                                      No active subjects for this program yet.
                                      Add them in Academic Setup.
                                    </FormDescription>
                                  ) : null}
                                  <FormMessage />
                                </FormItem>
                              )}
                            />
                            <FormField
                              control={form.control}
                              name={`assignments.${index}.yearLevel`}
                              render={({ field }) => (
                                <FormItem>
                                  <FormLabel>Year level</FormLabel>
                                  <Select
                                    value={field.value}
                                    onValueChange={(value) => {
                                      field.onChange(value)
                                      form.setValue(`assignments.${index}.section`, "")
                                      form.setValue(`assignments.${index}.campus`, "")
                                    }}
                                  >
                                    <FormControl>
                                      <SelectTrigger className="w-full">
                                        <SelectValue placeholder="Select year level" />
                                      </SelectTrigger>
                                    </FormControl>
                                    <SelectContent>
                                      {[...new Set(
                                        groupings
                                          .filter((row) =>
                                            String(row.programId) === selectedProgram &&
                                            row.status === "active" && row.assignable
                                          )
                                          .map((row) => row.yearLevel)
                                          .concat(field.value ? [field.value] : [])
                                      )].sort().map((year) => (
                                        <SelectItem key={year} value={year}>{year}</SelectItem>
                                      ))}
                                    </SelectContent>
                                  </Select>
                                  {selectedProgram && !groupings.some((row) =>
                                    String(row.programId) === selectedProgram && row.status === "active" && row.assignable
                                   ) ? (
                                    <FormDescription>
                                      Add an active class grouping for this program in Academic Setup.
                                    </FormDescription>
                                  ) : null}
                                  <FormMessage />
                                </FormItem>
                              )}
                            />
                            <FormField
                              control={form.control}
                              name={`assignments.${index}.section`}
                              render={({ field }) => (
                                <FormItem>
                                  <FormLabel>Section</FormLabel>
                                  <Select
                                    value={field.value}
                                    onValueChange={(value) => {
                                      field.onChange(value)
                                      // A campus the new section does not offer is cleared.
                                      const campus = form.getValues(
                                        `assignments.${index}.campus`
                                      )
                                      if (
                                        campus &&
                                        !isOfferedCampus(
                                          groupings,
                                          { ...groupingScope, section: value },
                                          campus
                                        )
                                      ) {
                                        form.setValue(`assignments.${index}.campus`, "")
                                      }
                                    }}
                                  >
                                    <FormControl>
                                      <SelectTrigger className="w-full">
                                        <SelectValue placeholder="Select section" />
                                      </SelectTrigger>
                                    </FormControl>
                                    <SelectContent>
                                      {sectionOptions.map((option) => (
                                        <SelectItem
                                          key={option.value}
                                          value={option.value}
                                          disabled={option.disabled}
                                        >
                                          {option.label}
                                        </SelectItem>
                                      ))}
                                    </SelectContent>
                                  </Select>
                                  {sectionOptions.length === 0 ? (
                                    <FormDescription>
                                      No class groupings for this program and
                                      year level. Add them in Academic Setup.
                                    </FormDescription>
                                  ) : null}
                                  <FormMessage />
                                </FormItem>
                              )}
                            />
                            <FormField
                              control={form.control}
                              name={`assignments.${index}.campus`}
                              render={({ field }) => (
                                <FormItem>
                                  <FormLabel>Campus</FormLabel>
                                  <Select
                                    value={field.value}
                                    onValueChange={field.onChange}
                                  >
                                    <FormControl>
                                      <SelectTrigger className="w-full">
                                        <SelectValue placeholder="Select campus" />
                                      </SelectTrigger>
                                    </FormControl>
                                    <SelectContent>
                                      {campusOptions.map((option) => (
                                        <SelectItem
                                          key={option.value}
                                          value={option.value}
                                          disabled={option.disabled}
                                        >
                                          {option.label}
                                        </SelectItem>
                                      ))}
                                    </SelectContent>
                                  </Select>
                                  <FormMessage />
                                </FormItem>
                              )}
                            />
                          </div>
                        </li>
                      )
                    })}
                  </ul>

                  {form.formState.errors.assignments?.root ? (
                    <p className="text-sm text-destructive">
                      {form.formState.errors.assignments.root.message}
                    </p>
                  ) : null}

                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    className={buttonMotion}
                    onClick={() =>
                      assignments.append({
                        ...emptyAssignment,
                        programId: bsitProgramIdValue,
                        yearLevel: PILOT_YEAR_LEVEL,
                      })
                    }
                  >
                    <Plus aria-hidden />
                    Add assignment
                  </Button>
                </div>
              ) : null}

              {step.id === "account" ? (
                <div className="grid gap-4 sm:grid-cols-2">
                  <div className="space-y-4">
                    {mode === "create" ? (
                      <>
                        <FormField
                          control={form.control}
                          name="password"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Password</FormLabel>
                              <FormControl>
                                <Input
                                  type="password"
                                  autoComplete="new-password"
                                  placeholder="Enter password"
                                  {...field}
                                />
                              </FormControl>
                              <FormDescription>
                                Use at least 8 characters.
                              </FormDescription>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={form.control}
                          name="confirmPassword"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Confirm password</FormLabel>
                              <FormControl>
                                <Input
                                  type="password"
                                  autoComplete="new-password"
                                  placeholder="Confirm password"
                                  {...field}
                                />
                              </FormControl>
                              <FormDescription>
                                Passwords must match.
                              </FormDescription>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                      </>
                    ) : (
                      <p className="text-sm text-muted-foreground text-pretty">
                        The login password is not editable here. Ask the teacher
                        to reset it from the sign-in page.
                      </p>
                    )}
                  </div>

                  <div className="rounded-lg border p-4">
                    <h4 className="text-sm font-semibold">Review Summary</h4>
                    <dl className="mt-3 space-y-1.5 text-sm">
                      <SummaryRow
                        label="Full name"
                        value={summary.fullName || "(not set)"}
                      />
                      <SummaryRow
                        label="Email"
                        value={summary.email || "(not set)"}
                      />
                      <SummaryRow
                        label="Teacher ID"
                        value={summary.teacherId || "(not set)"}
                      />
                      <SummaryRow
                        label="Department"
                        value={summary.department || "(not set)"}
                      />
                      <SummaryRow
                        label="Phone"
                        value={summary.phoneNumber || "(not set)"}
                      />
                      <SummaryRow
                        label="Programs"
                        value={
                          [...new Set((watchedAssignments ?? [])
                            .map((assignment) => programs.find((program) =>
                              String(program.id) === assignment.programId
                            )?.code)
                            .filter(Boolean)
                          )].join(", ") || "(not selected)"
                        }
                      />
                      <SummaryRow
                        label="Assignments"
                        value={
                          assignmentCount === 1
                            ? "1 class"
                            : `${assignmentCount} classes`
                        }
                      />
                      <SummaryRow
                        label="Sections"
                        value={
                          (watchedAssignments ?? [])
                            .map((assignment) => assignment?.section)
                            .filter(Boolean)
                            .join(", ") || "(not selected)"
                        }
                      />
                      <SummaryRow
                        label="Status"
                        value={
                          summary.status
                            ? accountStatusLabels[summary.status]
                            : "Active"
                        }
                      />
                    </dl>
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      className={cn("mt-4", buttonMotion)}
                      onClick={() => setStepIndex(0)}
                    >
                      Edit details
                    </Button>
                  </div>
                </div>
              ) : null}
            </div>

            <Separator />

            <DialogFooter className="sm:items-center sm:justify-between">
              {isLastStep ? (
                <p className="text-sm text-muted-foreground text-pretty sm:mr-auto">
                  Helper: You can navigate back to review or edit previous
                  information before adding the teacher.
                </p>
              ) : null}

              <div className="flex justify-end gap-2">
                {stepIndex === 0 ? (
                  <Button
                    type="button"
                    variant="ghost"
                    className={buttonMotion}
                    onClick={() => onOpenChange(false)}
                    disabled={isSubmitting}
                  >
                    Cancel
                  </Button>
                ) : (
                  <Button
                    type="button"
                    variant="outline"
                    className={buttonMotion}
                    onClick={goBack}
                    disabled={isSubmitting}
                  >
                    Back
                  </Button>
                )}

                {isLastStep ? (
                  <Button
                    key="save"
                    type="button"
                    onClick={handleSave}
                    className={buttonMotion}
                    disabled={isSubmitting}
                  >
                    {isSubmitting ? (
                      <Loader2 aria-hidden className="animate-spin" />
                    ) : null}
                    {mode === "create" ? "Add teacher" : "Save changes"}
                  </Button>
                ) : (
                  <Button
                    key="next"
                    type="button"
                    className={buttonMotion}
                    disabled={isSubmitting}
                    onClick={goNext}
                  >
                    Next
                  </Button>
                )}
              </div>
            </DialogFooter>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
  )
}
